document.addEventListener('keydown',e=>{if(!$('investigate').classList.contains('active'))return;let k=e.key.toLowerCase();if(k==='arrowup'||k==='w')move(0,-22);if(k==='arrowdown'||k==='s')move(0,22);if(k==='arrowleft'||k==='a')move(-22,0);if(k==='arrowright'||k==='d')move(22,0);if(k==='e')inspect()});$('up').onclick=()=>move(0,-22);$('down').onclick=()=>move(0,22);$('left').onclick=()=>move(-22,0);$('right').onclick=()=>move(22,0);$('inspect').onclick=inspect;$('trial').onclick=beginTrial;
function beginTrial(){good=false;$('trialTitle').textContent=cur.title;$('witnessImg').src=`assets/pokemon/${slug[cur.witness]}.png`;$('suspectImg').src=`assets/pokemon/${slug[cur.suspect]}.png`;$('witnessName').textContent=cur.witness;$('suspectName').textContent=cur.suspect;$('speaker').textContent=cur.witness+' 증인';$('testimony').textContent=cur.testimony;$('feedback').textContent='진술과 단서를 비교해 모순을 찾아보세요.';$('verdict').disabled=true;$('choices').innerHTML='';cur.choices.forEach((v,i)=>{let b=document.createElement('button');b.textContent=v;b.onclick=()=>{document.querySelectorAll('.choices button').forEach(x=>x.classList.remove('selected'));b.classList.add('selected');good=i===0;$('feedback').textContent=good?'정확한 증거입니다! 진술의 모순이 드러났습니다.':'이 증거로는 모순을 설명할 수 없습니다.';$('verdict').disabled=!good};$('choices').append(b)});show('trialScreen')}
$('verdict').onclick=()=>{if(!good)return;let fresh=!save.wins.includes(cur.id);if(fresh){save.wins.push(cur.id);save.rep+=20;if(cur.id%5===0)save.unlocked=Math.min(30,Math.max(save.unlocked,Math.floor(cur.id/5)+1));if(save.party.length<4&&!save.party.includes(cur.pokemon))save.party.push(cur.pokemon)}persist();$('resultText').textContent=cur.title+' 사건을 해결했습니다. '+cur.witness+'도 진실을 인정했습니다.';$('reward').textContent=fresh?'+20 평판 · '+(save.party.includes(cur.pokemon)?cur.pokemon+' 교화 팀 합류':'동료 슬롯 확인'):'이미 해결한 사건입니다.';$('next').onclick=()=>{let n=cases.find(x=>!save.wins.includes(x.id)&&x.region<save.unlocked);n?openCase(n.id):show('map')};show('result')};
